uniform float u_exaggerationRelativeHeight_17;uniform float u_verticalExaggeration_16;uniform vec2 u_radarCartographic_15;uniform mat4 u_radarToWorld_14;uniform mat4 u_eyeToRadar_13;uniform float u_maskHeightScaleM_12;uniform float u_maskHeightOffsetM_11;uniform float u_maskRadialStepM_10;uniform float u_maskAzimuthCount_9;uniform vec2 u_maskSize_8;uniform float u_maskMode_7;uniform sampler2D u_terrainMask_6;uniform float u_time_5;uniform float u_scanLineSpeed_4;uniform float u_scanLineCount_3;uniform float u_rimPower_2;uniform vec4 u_rimColor_1;uniform vec4 u_baseColor_0;
        float radarMaskHeight(float radialIndex, float azimuthIndex, float rowOffset)
        {
            float row = mod(azimuthIndex, u_maskAzimuthCount_9) + rowOffset;
            // Canvas rows start at the top; Cesium uploads canvas textures with flipY.
            vec2 uv = vec2((radialIndex + 0.5) / u_maskSize_8.x,
                           1.0 - (row + 0.5) / u_maskSize_8.y);
            vec2 bytes = floor(texture(u_terrainMask_6, uv).rg * 255.0 + 0.5);
            return u_maskHeightOffsetM_11 + (bytes.x * 256.0 + bytes.y) * u_maskHeightScaleM_12;
        }

        float radarConservativeMaskHeight(float radialIndex, float azimuthIndex, float rowOffset)
        {
            float r0 = floor(radialIndex);
            float r1 = min(r0 + 1.0, u_maskSize_8.x - 1.0);
            float a0 = floor(azimuthIndex);
            float a1 = a0 + 1.0;
            return max(max(radarMaskHeight(r0, a0, rowOffset), radarMaskHeight(r1, a0, rowOffset)),
                       max(radarMaskHeight(r0, a1, rowOffset), radarMaskHeight(r1, a1, rowOffset)));
        }

        void radarClipTerrain(czm_materialInput materialInput)
        {
            if (u_maskMode_7 < 0.5) return;
            // Work near the radar before reconstructing WGS84, keeping camera motion stable.
            vec3 local = (u_eyeToRadar_13 * vec4(-materialInput.positionToEyeEC, 1.0)).xyz;
            vec3 world = (u_radarToWorld_14 * vec4(local, 1.0)).xyz;
            float p = length(world.xy);
            float theta = atan(world.z * 6378137.0, p * 6356752.314245);
            float s = sin(theta);
            float c = cos(theta);
            float lat = atan(world.z + 0.006739496742276434 * 6356752.314245 * s * s * s,
                             p - 0.0066943799901413165 * 6378137.0 * c * c * c);
            float lon = atan(world.y, world.x);
            float sinLat = sin(lat);
            float n = 6378137.0 / sqrt(1.0 - 0.0066943799901413165 * sinLat * sinLat);
            float displayHeight = abs(cos(lat)) > 0.001 ? p / cos(lat) - n
                : abs(world.z) / abs(sinLat) - n * (1.0 - 0.0066943799901413165);
            float height = u_exaggerationRelativeHeight_17
                + (displayHeight - u_exaggerationRelativeHeight_17) / max(u_verticalExaggeration_16, 0.001);

            float deltaLon = lon - u_radarCartographic_15.x;
            float deltaLat = lat - u_radarCartographic_15.y;
            float halfLat = sin(deltaLat * 0.5);
            float halfLon = sin(deltaLon * 0.5);
            float hav = clamp(halfLat * halfLat + cos(lat) * cos(u_radarCartographic_15.y) * halfLon * halfLon, 0.0, 1.0);
            float range = 12742000.0 * atan(sqrt(hav), sqrt(max(0.0, 1.0 - hav)));
            float bearing = atan(sin(deltaLon) * cos(lat),
                cos(u_radarCartographic_15.y) * sin(lat) - sin(u_radarCartographic_15.y) * cos(lat) * cos(deltaLon));
            float azimuthIndex = mod(bearing / czm_twoPi + 1.0, 1.0) * u_maskAzimuthCount_9;
            float radialIndex = clamp(range / u_maskRadialStepM_10, 0.0, u_maskSize_8.x - 1.0);
            float groundHeight = radarConservativeMaskHeight(radialIndex, azimuthIndex, u_maskAzimuthCount_9);
            if (height < groundHeight + 2.0) discard;
            float visibleHeight = radarConservativeMaskHeight(radialIndex, azimuthIndex, 0.0);
            if (u_maskMode_7 < 1.5 && height + 1.0 < visibleHeight) discard;
            if (u_maskMode_7 > 1.5 && height >= visibleHeight) discard;
        }

        czm_material czm_getMaterial(czm_materialInput materialInput)
        {
            radarClipTerrain(materialInput);
            czm_material material = czm_getDefaultMaterial(materialInput);

            // Normal GIẢ: attribute normal đã được dựng sẵn bằng hướng xuyên tâm
            // từ tâm radar ra đỉnh (xem radarDomeGeometry.ts) nên ở đây chỉ cần chuẩn hoá.
            vec3 n = normalize(materialInput.normalEC);
            vec3 v = normalize(materialInput.positionToEyeEC);

            float facing = clamp(abs(dot(n, v)), 0.0, 1.0);
            float rim = pow(1.0 - facing, u_rimPower_2);

            // v = heightFraction của vòm (0 ở chân đế, 1 ở đỉnh)
            float phase = fract(materialInput.st.t * u_scanLineCount_3 - u_time_5 * u_scanLineSpeed_4);
            float scanLine = smoothstep(0.0, 0.05, phase) * (1.0 - smoothstep(0.95, 1.0, phase));

            vec3 rgb = mix(u_baseColor_0.rgb, u_rimColor_1.rgb, clamp(rim * 0.9, 0.0, 1.0));
            rgb += u_rimColor_1.rgb * (scanLine * 0.08);

            float alpha = clamp(max(u_baseColor_0.a, 0.14) + rim * 0.42 + scanLine * 0.08, 0.0, 1.0);

            material.diffuse = rgb;
            material.alpha = alpha;
            material.specular = 0.0;
            material.shininess = 1.0;

            return material;
        }
